const 대기중행 = items.filter(item => item.json['상태'] === '대기중');

if (대기중행.length === 0) {
  return [{ json: { __발행없음: true } }];
}

const row = 대기중행[0].json;
return [{
  json: {
    __발행없음: false,
    메인키워드: row['메인 키워드'] || '',
    서브키워드: row['서브키워드'] || '',
    포함키워드: row['포함할 키워드'] || '',
    서브수: parseInt(row['서브키워드 수']) || 3
  }
}];

const d = items[0].json;
const keyword = d.메인키워드;
const subKeywords = d.서브키워드;
const includeKeywords = d.포함키워드;
const subCount = d.서브수;

const today = new Date();
const dateStr = today.toISOString().split('T')[0];
const dateCompact = dateStr.replace(/-/g, '');
const slug = keyword
  .replace(/\s+/g, '-')
  .replace(/[^a-zA-Z0-9가-힣-]/g, '')
  .substring(0, 40) + '-' + dateCompact;

const gptBody = {
  model: 'gpt-4o',
  max_tokens: 3000,
  temperature: 0.8,
  messages: [
    {
      role: 'system',
      content: '당신은 타로·운세·사주 분야 SEO 전문 블로그 작가입니다. 신비롭고 흥미로운 문체로 독자가 공감하고 몰입할 수 있는 콘텐츠를 작성합니다. 데스티니워(destiny-war.com)는 AI 타로 상담 서비스입니다. 출력은 반드시 순수 HTML 형식(Markdown 사용 금지)으로 합니다.'
    },
    {
      role: 'user',
      content: `아래 조건으로 SEO 최적화 블로그 글을 HTML 형식으로 작성해주세요.

[키워드 조건]
- 메인 키워드: ${keyword}
- 서브키워드: ${subKeywords}
- 반드시 포함할 단어: ${includeKeywords}
- 서브키워드 각각 ${subCount}회 이상 자연스럽게 포함

[작성 규칙]
1. 분량: 1,500자 이상
2. <h2> 소제목 3개 이상, <h3>도 활용
3. <p>, <ul>, <li> 태그 사용
4. <body>, <html>, <head> 태그 제외
5. 첫 번째 <p>에 메인 키워드 포함
6. 독자의 고민과 감정에 공감하는 문체
7. 타로 카드, 운명, 자기 성찰과 관련된 내용 자연스럽게 포함
8. 마지막 소제목에서 AI 타로 상담(데스티니워)을 자연스럽게 소개`
    }
  ]
};

return [{
  json: {
    keyword, subKeywords, includeKeywords, subCount,
    slug, dateStr,
    gptBody
  }
}];

const gptResult = items[0].json;
const prevData = $('슬러그 생성 및 GPT 요청 준비').first().json;

const htmlContent = gptResult.choices[0].message.content;

const titleMatch = htmlContent.match(/<h[12][^>]*>([^<]+)<\/h[12]>/i);
const title = titleMatch
  ? titleMatch[1].replace(/<[^>]+>/g, '').trim()
  : prevData.keyword + ' 완벽 가이드';

const excerptMatch = htmlContent.match(/<p[^>]*>([\s\S]*?)<\/p>/i);
const rawExcerpt = excerptMatch
  ? excerptMatch[1].replace(/<[^>]+>/g, '').trim()
  : prevData.keyword + ' 관련 타로 가이드입니다.';
const excerpt = rawExcerpt.substring(0, 150) + (rawExcerpt.length > 150 ? '...' : '');

const dalleBody = {
  model: 'dall-e-3',
  prompt: `신비롭고 아름다운 타로 카드 장면. 달빛 아래 펼쳐진 타로 카드들, 깊은 우주 별빛 배경, 보라색과 금색 분위기. "${prevData.keyword}" 주제와 관련된 신비로운 이미지. 이미지 안에 텍스트나 글자 없음. 디지털 아트 스타일.`,
  size: '1792x1024',
  quality: 'standard',
  n: 1
};

return [{
  json: {
    title, excerpt, htmlContent,
    keyword: prevData.keyword,
    slug: prevData.slug,
    dateStr: prevData.dateStr,
    dalleBody
  }
}];

const dalleResult = items[0].json;
const parsedData = $('GPT 응답 파싱 및 DALL-E 요청 준비').first().json;

const imageUrl = dalleResult.data[0].url;

// 이미지를 본문 상단에 추가한 최종 HTML
const imageTag = `<img src="${imageUrl}" alt="${parsedData.keyword}" style="width:100%;height:auto;border-radius:12px;margin-bottom:24px;" />`;
const finalHtml = imageTag + '\n' + parsedData.htmlContent;

// PostgreSQL slug는 영문만 허용 (한글 slug를 영문으로 변환)
const safeSlug = parsedData.slug
  .replace(/[가-힣]/g, '')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '') || 'blog-' + parsedData.dateStr.replace(/-/g, '');

return [{
  json: {
    slug: safeSlug,
    title: parsedData.title,
    excerpt: parsedData.excerpt,
    contentHtml: finalHtml,
    keyword: parsedData.keyword,
    dateStr: parsedData.dateStr
  }
}];
